/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_user_addresses_after_insert` AFTER INSERT ON `tb_user_addresses` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_user`, `table_description`)
    VALUES (
        'tb_user_addresses',
        'Create',
        USER(),
        CONCAT(
            'ID: ', NEW.ID,
            '; user_ID: ', NEW.user_ID,
            '; address_label: ', NEW.address_label,
