/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_address_components_after_insert` AFTER INSERT ON `tbd_address_components` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_user`, `table_description`)
    VALUES (
        'tbd_address_components',
        'Create',
        USER(),
        CONCAT(
            'ID: ', NEW.ID,
            '; address_ID: ', NEW.address_ID,
            '; value: ', NEW.value,
            '; component_type: ', NEW.component_type,
            '; status: ', CAST(NEW.status AS UNSIGNED),
            '; address_sup_ID: ', COALESCE(CAST(NEW.address_sup_ID AS CHAR), 'NULL'),
            '; creation_date: ', NEW.creation_date,
            '; last_update: ', COALESCE(CAST(NEW.last_update AS CHAR), 'NULL')
        )
    );
